// Approach: Each edge represents one lowercase letter. A terminal flag distinguishes a complete word
//   from its prefixes.
#include <array>
#include <memory>
#include <string>
using namespace std;
class Trie {
    struct Node {
        array<unique_ptr<Node>, 26> child{};
        bool end = false;
    };
    Node root;
public:
    void insert(const string& word) {
        Node* node = &root;
        for (char ch : word) {
            int i = ch - 'a'; // lowercase input
            if (!node->child[i]) node->child[i] = make_unique<Node>();
            node = node->child[i].get();
        }
        node->end = true;
    }
    bool search(const string& word) const {
        const Node* node = &root;
        for (char ch : word) {
            int i = ch - 'a';
            if (!node->child[i]) return false;
            node = node->child[i].get();
        }
        return node->end;
    }
    bool startsWith(const string& prefix) const {
        const Node* node = &root;
        for (char ch : prefix) {
            int i = ch - 'a';
            if (!node->child[i]) return false;
            node = node->child[i].get();
        }
        return true;
    }
};

