// Approach: Count how many words pass through each node and how many end there; decrement both counts
//   when erasing an existing word.
#include <array>
#include <memory>
#include <string>
using namespace std;
class CountingTrie {
    struct Node {
        array<unique_ptr<Node>, 26> child{};
        int pass = 0, end = 0;
    };
    Node root;
public:
    void insert(const string& word) {
        ++root.pass;
        Node* node = &root;
        for (char ch : word) {
            int i = ch - 'a'; // lowercase input
            if (!node->child[i]) node->child[i] = make_unique<Node>();
            node = node->child[i].get();
            ++node->pass;
        }
        ++node->end;
    }
    int countWordsEqualTo(const string& word) const {
        const Node* node = &root;
        for (char ch : word) {
            int i = ch - 'a';
            if (!node->child[i]) return 0;
            node = node->child[i].get();
        }
        return node->end;
    }
    int countWordsStartingWith(const string& prefix) const {
        const Node* node = &root;
        for (char ch : prefix) {
            int i = ch - 'a';
            if (!node->child[i]) return 0;
            node = node->child[i].get();
        }
        return node->pass;
    }
    void erase(const string& word) {
        if (!countWordsEqualTo(word)) return;
        --root.pass;
        Node* node = &root;
        for (char ch : word) {
            node = node->child[ch - 'a'].get();
            --node->pass;
        }
        --node->end;
    }
};

s17-longest-string-with-all-prefixes.code:
// Approach: After inserting every word, a word qualifies only if every node along its path ends a
//   word. Prefer longer words, then lexicographically smaller ones.
#include <array>
#include <memory>
#include <string>
#include <vector>
using namespace std;
string longestCompleteString(const vector<string>& words) {
    struct Node {
        array<unique_ptr<Node>, 26> child{};
        bool end = false;
    };
    Node root;
    for (const string& word : words) {
        Node* node = &root;
        for (char ch : word) {
            int i = ch - 'a';
            if (!node->child[i]) node->child[i] = make_unique<Node>();
            node = node->child[i].get();
        }
        node->end = true;
    }
    string best;
    for (const string& word : words) {
        const Node* node = &root;
        bool complete = true;
        for (char ch : word) {
            node = node->child[ch - 'a'].get();
            if (!node->end) { complete = false; break; }
        }
        if (complete && (word.size() > best.size()
            || (word.size() == best.size() && word < best))) best = word;
    }
    return best.empty() ? "None" : best;
}

s17-number-of-distinct-substrings-in-a-s.code:
// Approach: Insert every suffix into a trie. Every newly created node corresponds to one distinct
//   nonempty substring.
#include <array>
#include <string>
#include <vector>
using namespace std;
long long countDistinctSubstrings(const string& s) {
    struct Node { array<int, 26> next; Node() { next.fill(-1); } };
    vector<Node> trie(1);
    long long count = 1; // include the empty substring
    for (int start = 0; start < (int)s.size(); ++start) {
        int node = 0;
        for (int j = start; j < (int)s.size(); ++j) {
            int letter = s[j] - 'a'; // lowercase input
            if (trie[node].next[letter] == -1) {
                trie[node].next[letter] = (int)trie.size();
                trie.emplace_back();
                ++count;
            }
            node = trie[node].next[letter];
        }
    }
    return count;
}

s17-bit-prerequisites-for-trie-problems.code:
// Approach: Read, set, clear, and flip a bit with shifts and masks; XOR is one exactly when bits
//   differ.
#include <cstdint>
using namespace std;
bool isBitSet(uint32_t value, int bit) {
    return (value >> bit) & 1U;
}
uint32_t setBit(uint32_t value, int bit) {
    return value | (1U << bit);
}
uint32_t clearBit(uint32_t value, int bit) {
    return value & ~(1U << bit);
}
uint32_t flipBit(uint32_t value, int bit) {
    return value ^ (1U << bit);
}
// Valid bit positions are 0 through 31 for uint32_t.

