// Approach: Insert numbers into a bit trie. For each bit, try the opposite branch to maximize XOR.
#include <algorithm>
#include <array>
#include <cstdint>
#include <vector>
using namespace std;
uint32_t findMaximumXOR(const vector<uint32_t>& values) {
    if (values.size() < 2) return 0;
    struct Node { array<int, 2> next{-1, -1}; };
    // Store bits from most significant to least; prefer the opposite bit for XOR.
    vector<Node> trie(1);
    auto insert = [&](uint32_t x) {
        int node = 0;
        for (int bit = 31; bit >= 0; --bit) {
            int b = (x >> bit) & 1U;
            if (trie[node].next[b] == -1) {
                trie[node].next[b] = (int)trie.size();
                trie.emplace_back();
            }
            node = trie[node].next[b];
        }
    };
    auto bestXor = [&](uint32_t x) {
        int node = 0;
        uint32_t answer = 0;
        for (int bit = 31; bit >= 0; --bit) {
            int b = (x >> bit) & 1U;
            int opposite = trie[node].next[1 - b];
            if (opposite != -1) {
                answer |= 1U << bit;
                node = opposite;
            } else node = trie[node].next[b];
        }
        return answer;
    };
    insert(values[0]);
    uint32_t answer = 0;
    for (int i = 1; i < (int)values.size(); ++i) {
        answer = max(answer, bestXor(values[i]));
        insert(values[i]);
    }
    return answer;
}

