// Approach: Sort values and offline queries by maximum allowed value. Insert eligible numbers into a
//   bit trie before answering each query.
#include <algorithm>
#include <array>
#include <tuple>
#include <vector>
using namespace std;
vector<int> maximizeXor(vector<int> values,
                        const vector<array<int, 2>>& queries) {
    struct Node { array<int, 2> next{-1, -1}; };
    vector<Node> trie(1);
    auto insert = [&](int value) {
        int node = 0;
        for (int bit = 30; bit >= 0; --bit) {
            int b = (value >> bit) & 1;
            if (trie[node].next[b] == -1) {
                trie[node].next[b] = (int)trie.size();
                trie.emplace_back();
            }
            node = trie[node].next[b];
        }
    };
    auto bestXor = [&](int value) {
        int node = 0, answer = 0;
        for (int bit = 30; bit >= 0; --bit) {
            int b = (value >> bit) & 1;
            if (trie[node].next[1 - b] != -1) {
                answer |= 1 << bit;
                node = trie[node].next[1 - b];
            } else node = trie[node].next[b];
        }
        return answer;
    };
    sort(values.begin(), values.end());
    vector<tuple<int, int, int>> order;
    for (int i = 0; i < (int)queries.size(); ++i)
        order.emplace_back(queries[i][1], queries[i][0], i);
    sort(order.begin(), order.end());
    vector<int> answer(queries.size(), -1);
    int inserted = 0;
    for (auto [limit, x, index] : order) {
        while (inserted < (int)values.size() && values[inserted] <= limit)
            insert(values[inserted++]);
        if (inserted) answer[index] = bestXor(x);
    }
    return answer; // inputs are nonnegative 31-bit integers
}
